// 1. Create Scheduled Job
POST /api/v1/jobs
Headers:
  Idempotency-Key: job_billing_invoice_monthly
Request:
{
  "tenant_id": "tnt_8821",
  "name": "monthly-invoice-rollup",
  "schedule_type": "CRON",
  "cron_expression": "0 0 1 * *",
  "target_topic": "billing.jobs.execute",
  "payload": { "currency": "USD" },
  "timeout_seconds": 300,
  "max_retries": 3
}
Response (201 Created):
{
  "job_id": "job_01HV9Z8821",
  "next_execution_id": "exec_991023",
  "next_run_at": "2026-10-01T00:00:00Z",
  "assigned_shard_id": 14
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY job_definitions (Sharded PostgreSQL / CockroachDB) {
  [PK ] job_id                 UUID
  [IDX] tenant_id              UUID
        schedule_cron          VARCHAR(64)
        target_webhook_Or_topic VARCHAR(255)
        max_retries            INT
}

ENTITY scheduled_slots (Cassandra / Sharded Time-Bucket Table) {
  [PK ] minute_bucket          BIGINT (Partition Key)
  [PK ] shard_id               INT (0..63 Partition Key)
  [PK ] due_epoch_ms           BIGINT (Clustering ASC)
  [FK ] execution_id           UUID
  [FK ] job_id                 UUID
}

ENTITY job_executions (Sharded PostgreSQL) {
  [PK ] execution_id           UUID
  [FK ] job_id                 UUID
        state                  ENUM('DUE','LEASED','SUCCEEDED','DLQ')
  [IDX] lease_expires_at       TIMESTAMPTZ
        fencing_token          BIGINT (Monotonic)
}

// Relationships: job_definitions --(1 : N (schedules time slots))--> scheduled_slots --(1 : 1 (tracks execution lease))--> job_executions
